mkitem!{mkimpl!{impl < 'tcx > InferCtxt < 'tcx > { # [doc = " Canonicalizes a query value `V`. When we canonicalize a query,"] # [doc = " we not only canonicalize unbound inference variables, but we"] # [doc = " *also* replace all free regions whatsoever. So for example a"] # [doc = " query like `T: Trait<'static>` would be canonicalized to"] # [doc = ""] # [doc = " ```text"] # [doc = " T: Trait<'?0>"] # [doc = " ```"] # [doc = ""] # [doc = " with a mapping M that maps `'?0` to `'static`."] # [doc = ""] # [doc = " To get a good understanding of what is happening here, check"] # [doc = " out the [chapter in the rustc dev guide][c]."] # [doc = ""] # [doc = " [c]: https://rust-lang.github.io/chalk/book/canonical_queries/canonicalization.html#canonicalizing-the-query"] pub fn canonicalize_query < V > (& self , value : ty :: ParamEnvAnd < 'tcx , V > , query_state : & mut OriginalQueryValues < 'tcx > ,) -> CanonicalQueryInput < 'tcx , ty :: ParamEnvAnd < 'tcx , V > > where V : TypeFoldable < TyCtxt < 'tcx > > , { let ty :: ParamEnvAnd { param_env , value } = value ; let canonical_param_env = self . tcx . canonical_param_env_cache . get_or_insert (self . tcx , param_env , query_state , | tcx , param_env , query_state | { Canonicalizer :: canonicalize (param_env , None , tcx , & CanonicalizeFreeRegionsOtherThanStatic , query_state ,) } ,) ; let canonical = Canonicalizer :: canonicalize_with_base (canonical_param_env , value , Some (self) , self . tcx , & CanonicalizeAllFreeRegions , query_state ,) . unchecked_map (| (param_env , value) | param_env . and (value)) ; CanonicalQueryInput { canonical , typing_mode : self . typing_mode () } } # [doc = " Canonicalizes a query *response* `V`. When we canonicalize a"] # [doc = " query response, we only canonicalize unbound inference"] # [doc = " variables, and we leave other free regions alone. So,"] # [doc = " continuing with the example from `canonicalize_query`, if"] # [doc = " there was an input query `T: Trait<'static>`, it would have"] # [doc = " been canonicalized to"] # [doc = ""] # [doc = " ```text"] # [doc = " T: Trait<'?0>"] # [doc = " ```"] # [doc = ""] # [doc = " with a mapping M that maps `'?0` to `'static`. But if we found that there"] # [doc = " exists only one possible impl of `Trait`, and it looks like"] # [doc = " ```ignore (illustrative)"] # [doc = " impl<T> Trait<'static> for T { .. }"] # [doc = " ```"] # [doc = " then we would prepare a query result R that (among other"] # [doc = " things) includes a mapping to `'?0 := 'static`. When"] # [doc = " canonicalizing this query result R, we would leave this"] # [doc = " reference to `'static` alone."] # [doc = ""] # [doc = " To get a good understanding of what is happening here, check"] # [doc = " out the [chapter in the rustc dev guide][c]."] # [doc = ""] # [doc = " [c]: https://rust-lang.github.io/chalk/book/canonical_queries/canonicalization.html#canonicalizing-the-query-result"] pub fn canonicalize_response < V > (& self , value : V) -> Canonical < 'tcx , V > where V : TypeFoldable < TyCtxt < 'tcx > > , { let mut query_state = OriginalQueryValues :: default () ; Canonicalizer :: canonicalize (value , Some (self) , self . tcx , & CanonicalizeQueryResponse , & mut query_state ,) } pub fn canonicalize_user_type_annotation < V > (& self , value : V) -> Canonical < 'tcx , V > where V : TypeFoldable < TyCtxt < 'tcx > > , { let mut query_state = OriginalQueryValues :: default () ; Canonicalizer :: canonicalize (value , Some (self) , self . tcx , & CanonicalizeUserTypeAnnotation , & mut query_state ,) } }}}
mkitem!{mktrait!{# [doc = " Controls how we canonicalize \"free regions\" that are not inference"] # [doc = " variables. This depends on what we are canonicalizing *for* --"] # [doc = " e.g., if we are canonicalizing to create a query, we want to"] # [doc = " replace those with inference variables, since we want to make a"] # [doc = " maximally general query. But if we are canonicalizing a *query"] # [doc = " response*, then we don't typically replace free regions, as they"] # [doc = " must have been introduced from other parts of the system."] trait CanonicalizeMode { fn canonicalize_free_region < 'tcx > (& self , canonicalizer : & mut Canonicalizer < '_ , 'tcx > , r : ty :: Region < 'tcx > ,) -> ty :: Region < 'tcx > ; fn any (& self) -> bool ; fn preserve_universes (& self) -> bool ; }}}
