mkitem!{mkimpl!{impl < 'cx , 'tcx > TypeFolder < TyCtxt < 'tcx > > for Canonicalizer < 'cx , 'tcx > { fn cx (& self) -> TyCtxt < 'tcx > { self . tcx } fn fold_binder < T > (& mut self , t : ty :: Binder < 'tcx , T >) -> ty :: Binder < 'tcx , T > where T : TypeFoldable < TyCtxt < 'tcx > > , { self . binder_index . shift_in (1) ; let t = t . super_fold_with (self) ; self . binder_index . shift_out (1) ; t } fn fold_region (& mut self , r : ty :: Region < 'tcx >) -> ty :: Region < 'tcx > { match r . kind () { ty :: ReBound (index , ..) => { if index >= self . binder_index { bug ! ("escaping late-bound region during canonicalization") ; } else { r } } ty :: ReStatic | ty :: ReEarlyParam (..) | ty :: ReError (_) | ty :: ReLateParam (_) | ty :: RePlaceholder (..) | ty :: ReVar (_) | ty :: ReErased => self . canonicalize_mode . canonicalize_free_region (self , r) , } } fn fold_ty (& mut self , mut t : Ty < 'tcx >) -> Ty < 'tcx > { match * t . kind () { ty :: Infer (ty :: TyVar (mut vid)) => { let root_vid = self . infcx . unwrap () . root_var (vid) ; if root_vid != vid { t = Ty :: new_var (self . tcx , root_vid) ; vid = root_vid ; } debug ! ("canonical: type var found with vid {:?}" , vid) ; match self . infcx . unwrap () . probe_ty_var (vid) { Ok (t) => { debug ! ("(resolved to {:?})" , t) ; self . fold_ty (t) } Err (mut ui) => { if ! self . canonicalize_mode . preserve_universes () { ui = ty :: UniverseIndex :: ROOT ; } let sub_root = self . get_or_insert_sub_root (vid) ; self . canonicalize_ty_var (CanonicalVarKind :: Ty { ui , sub_root } , t) } } } ty :: Infer (ty :: IntVar (vid)) => { let nt = self . infcx . unwrap () . opportunistic_resolve_int_var (vid) ; if nt != t { return self . fold_ty (nt) ; } else { self . canonicalize_ty_var (CanonicalVarKind :: Int , t) } } ty :: Infer (ty :: FloatVar (vid)) => { let nt = self . infcx . unwrap () . opportunistic_resolve_float_var (vid) ; if nt != t { return self . fold_ty (nt) ; } else { self . canonicalize_ty_var (CanonicalVarKind :: Float , t) } } ty :: Infer (ty :: FreshTy (_) | ty :: FreshIntTy (_) | ty :: FreshFloatTy (_)) => { bug ! ("encountered a fresh type during canonicalization") } ty :: Placeholder (mut placeholder) => { if ! self . canonicalize_mode . preserve_universes () { placeholder . universe = ty :: UniverseIndex :: ROOT ; } self . canonicalize_ty_var (CanonicalVarKind :: PlaceholderTy (placeholder) , t) } ty :: Bound (debruijn , _) => { if debruijn >= self . binder_index { bug ! ("escaping bound type during canonicalization") } else { t } } ty :: Closure (..) | ty :: CoroutineClosure (..) | ty :: Coroutine (..) | ty :: CoroutineWitness (..) | ty :: Bool | ty :: Char | ty :: Int (..) | ty :: Uint (..) | ty :: Float (..) | ty :: Adt (..) | ty :: Str | ty :: Error (_) | ty :: Array (..) | ty :: Slice (..) | ty :: RawPtr (..) | ty :: Ref (..) | ty :: FnDef (..) | ty :: FnPtr (..) | ty :: Dynamic (..) | ty :: UnsafeBinder (_) | ty :: Never | ty :: Tuple (..) | ty :: Alias (..) | ty :: Foreign (..) | ty :: Pat (..) | ty :: Param (..) => { if t . flags () . intersects (self . needs_canonical_flags) { t . super_fold_with (self) } else { t } } } } fn fold_const (& mut self , mut ct : ty :: Const < 'tcx >) -> ty :: Const < 'tcx > { match ct . kind () { ty :: ConstKind :: Infer (InferConst :: Var (mut vid)) => { let root_vid = self . infcx . unwrap () . root_const_var (vid) ; if root_vid != vid { ct = ty :: Const :: new_var (self . tcx , root_vid) ; vid = root_vid ; } debug ! ("canonical: const var found with vid {:?}" , vid) ; match self . infcx . unwrap () . probe_const_var (vid) { Ok (c) => { debug ! ("(resolved to {:?})" , c) ; return self . fold_const (c) ; } Err (mut ui) => { if ! self . canonicalize_mode . preserve_universes () { ui = ty :: UniverseIndex :: ROOT ; } return self . canonicalize_const_var (CanonicalVarKind :: Const (ui) , ct) ; } } } ty :: ConstKind :: Infer (InferConst :: Fresh (_)) => { bug ! ("encountered a fresh const during canonicalization") } ty :: ConstKind :: Bound (debruijn , _) => { if debruijn >= self . binder_index { bug ! ("escaping bound const during canonicalization") } else { return ct ; } } ty :: ConstKind :: Placeholder (placeholder) => { return self . canonicalize_const_var (CanonicalVarKind :: PlaceholderConst (placeholder) , ct) ; } _ => { } } if ct . flags () . intersects (self . needs_canonical_flags) { ct . super_fold_with (self) } else { ct } } fn fold_predicate (& mut self , p : ty :: Predicate < 'tcx >) -> ty :: Predicate < 'tcx > { if p . flags () . intersects (self . needs_canonical_flags) { p . super_fold_with (self) } else { p } } fn fold_clauses (& mut self , c : ty :: Clauses < 'tcx >) -> ty :: Clauses < 'tcx > { if c . flags () . intersects (self . needs_canonical_flags) { c . super_fold_with (self) } else { c } } }}}
mkitem!{mkimpl!{impl < 'cx , 'tcx > Canonicalizer < 'cx , 'tcx > { # [doc = " The main `canonicalize` method, shared impl of"] # [doc = " `canonicalize_query` and `canonicalize_response`."] fn canonicalize < V > (value : V , infcx : Option < & InferCtxt < 'tcx > > , tcx : TyCtxt < 'tcx > , canonicalize_region_mode : & dyn CanonicalizeMode , query_state : & mut OriginalQueryValues < 'tcx > ,) -> Canonical < 'tcx , V > where V : TypeFoldable < TyCtxt < 'tcx > > , { let base = Canonical { max_universe : ty :: UniverseIndex :: ROOT , variables : List :: empty () , value : () , } ; Canonicalizer :: canonicalize_with_base (base , value , infcx , tcx , canonicalize_region_mode , query_state ,) . unchecked_map (| (() , val) | val) } fn canonicalize_with_base < U , V > (base : Canonical < 'tcx , U > , value : V , infcx : Option < & InferCtxt < 'tcx > > , tcx : TyCtxt < 'tcx > , canonicalize_region_mode : & dyn CanonicalizeMode , query_state : & mut OriginalQueryValues < 'tcx > ,) -> Canonical < 'tcx , (U , V) > where V : TypeFoldable < TyCtxt < 'tcx > > , { let needs_canonical_flags = if canonicalize_region_mode . any () { TypeFlags :: HAS_INFER | TypeFlags :: HAS_PLACEHOLDER | TypeFlags :: HAS_FREE_REGIONS } else { TypeFlags :: HAS_INFER | TypeFlags :: HAS_PLACEHOLDER } ; if ! value . has_type_flags (needs_canonical_flags) { return base . unchecked_map (| b | (b , value)) ; } let mut canonicalizer = Canonicalizer { infcx , tcx , canonicalize_mode : canonicalize_region_mode , needs_canonical_flags , variables : SmallVec :: from_slice (base . variables) , query_state , indices : FxHashMap :: default () , sub_root_lookup_table : Default :: default () , binder_index : ty :: INNERMOST , } ; if canonicalizer . query_state . var_values . spilled () { canonicalizer . indices = canonicalizer . query_state . var_values . iter () . enumerate () . map (| (i , & kind) | (kind , BoundVar :: new (i))) . collect () ; } let out_value = value . fold_with (& mut canonicalizer) ; debug_assert ! (! out_value . has_infer () && ! out_value . has_placeholders ()) ; let canonical_variables = tcx . mk_canonical_var_kinds (& canonicalizer . universe_canonicalized_variables ()) ; let max_universe = canonical_variables . iter () . map (| cvar | cvar . universe ()) . max () . unwrap_or (ty :: UniverseIndex :: ROOT) ; Canonical { max_universe , variables : canonical_variables , value : (base . value , out_value) } } # [doc = " Creates a canonical variable replacing `kind` from the input,"] # [doc = " or returns an existing variable if `kind` has already been"] # [doc = " seen. `kind` is expected to be an unbound variable (or"] # [doc = " potentially a free region)."] fn canonical_var (& mut self , var_kind : CanonicalVarKind < 'tcx > , value : GenericArg < 'tcx > ,) -> BoundVar { let Canonicalizer { variables , query_state , indices , .. } = self ; let var_values = & mut query_state . var_values ; let universe = var_kind . universe () ; if universe != ty :: UniverseIndex :: ROOT { assert ! (self . canonicalize_mode . preserve_universes ()) ; match query_state . universe_map . binary_search (& universe) { Err (idx) => query_state . universe_map . insert (idx , universe) , Ok (_) => { } } } if ! var_values . spilled () { if let Some (idx) = var_values . iter () . position (| & v | v == value) { BoundVar :: new (idx) } else { variables . push (var_kind) ; var_values . push (value) ; assert_eq ! (variables . len () , var_values . len ()) ; if var_values . spilled () { assert ! (indices . is_empty ()) ; * indices = var_values . iter () . enumerate () . map (| (i , & value) | (value , BoundVar :: new (i))) . collect () ; } BoundVar :: new (var_values . len () - 1) } } else { * indices . entry (value) . or_insert_with (| | { variables . push (var_kind) ; var_values . push (value) ; assert_eq ! (variables . len () , var_values . len ()) ; BoundVar :: new (variables . len () - 1) }) } } fn get_or_insert_sub_root (& mut self , vid : ty :: TyVid) -> ty :: BoundVar { let root_vid = self . infcx . unwrap () . sub_unification_table_root_var (vid) ; let idx = * self . sub_root_lookup_table . entry (root_vid) . or_insert_with (| | self . variables . len ()) ; ty :: BoundVar :: from (idx) } # [doc = " Replaces the universe indexes used in `var_values` with their index in"] # [doc = " `query_state.universe_map`. This minimizes the maximum universe used in"] # [doc = " the canonicalized value."] fn universe_canonicalized_variables (self) -> SmallVec < [CanonicalVarKind < 'tcx > ; 8] > { if self . query_state . universe_map . len () == 1 { return self . variables ; } let reverse_universe_map : FxHashMap < ty :: UniverseIndex , ty :: UniverseIndex > = self . query_state . universe_map . iter () . enumerate () . map (| (idx , universe) | (* universe , ty :: UniverseIndex :: from_usize (idx))) . collect () ; self . variables . iter () . map (| & kind | match kind { CanonicalVarKind :: Int | CanonicalVarKind :: Float => { return kind ; } CanonicalVarKind :: Ty { ui , sub_root } => { CanonicalVarKind :: Ty { ui : reverse_universe_map [& ui] , sub_root } } CanonicalVarKind :: Region (u) => CanonicalVarKind :: Region (reverse_universe_map [& u]) , CanonicalVarKind :: Const (u) => CanonicalVarKind :: Const (reverse_universe_map [& u]) , CanonicalVarKind :: PlaceholderTy (placeholder) => { CanonicalVarKind :: PlaceholderTy (ty :: Placeholder { universe : reverse_universe_map [& placeholder . universe] , .. placeholder }) } CanonicalVarKind :: PlaceholderRegion (placeholder) => { CanonicalVarKind :: PlaceholderRegion (ty :: Placeholder { universe : reverse_universe_map [& placeholder . universe] , .. placeholder }) } CanonicalVarKind :: PlaceholderConst (placeholder) => { CanonicalVarKind :: PlaceholderConst (ty :: Placeholder { universe : reverse_universe_map [& placeholder . universe] , .. placeholder }) } }) . collect () } # [doc = " Shorthand helper that creates a canonical region variable for"] # [doc = " `r` (always in the root universe). The reason that we always"] # [doc = " put these variables into the root universe is because this"] # [doc = " method is used during **query construction:** in that case, we"] # [doc = " are taking all the regions and just putting them into the most"] # [doc = " generic context we can. This may generate solutions that don't"] # [doc = " fit (e.g., that equate some region variable with a placeholder"] # [doc = " it can't name) on the caller side, but that's ok, the caller"] # [doc = " can figure that out. In the meantime, it maximizes our"] # [doc = " caching."] # [doc = ""] # [doc = " (This works because unification never fails -- and hence trait"] # [doc = " selection is never affected -- due to a universe mismatch.)"] fn canonical_var_for_region_in_root_universe (& mut self , r : ty :: Region < 'tcx > ,) -> ty :: Region < 'tcx > { self . canonical_var_for_region (CanonicalVarKind :: Region (ty :: UniverseIndex :: ROOT) , r) } # [doc = " Creates a canonical variable (with the given `info`)"] # [doc = " representing the region `r`; return a region referencing it."] fn canonical_var_for_region (& mut self , var_kind : CanonicalVarKind < 'tcx > , r : ty :: Region < 'tcx > ,) -> ty :: Region < 'tcx > { let var = self . canonical_var (var_kind , r . into ()) ; let br = ty :: BoundRegion { var , kind : ty :: BoundRegionKind :: Anon } ; ty :: Region :: new_bound (self . cx () , self . binder_index , br) } # [doc = " Given a type variable `ty_var` of the given kind, first check"] # [doc = " if `ty_var` is bound to anything; if so, canonicalize"] # [doc = " *that*. Otherwise, create a new canonical variable for"] # [doc = " `ty_var`."] fn canonicalize_ty_var (& mut self , var_kind : CanonicalVarKind < 'tcx > , ty_var : Ty < 'tcx > ,) -> Ty < 'tcx > { debug_assert ! (! self . infcx . is_some_and (| infcx | ty_var != infcx . shallow_resolve (ty_var))) ; let var = self . canonical_var (var_kind , ty_var . into ()) ; let bt = ty :: BoundTy { var , kind : ty :: BoundTyKind :: Anon } ; Ty :: new_bound (self . tcx , self . binder_index , bt) } # [doc = " Given a type variable `const_var` of the given kind, first check"] # [doc = " if `const_var` is bound to anything; if so, canonicalize"] # [doc = " *that*. Otherwise, create a new canonical variable for"] # [doc = " `const_var`."] fn canonicalize_const_var (& mut self , var_kind : CanonicalVarKind < 'tcx > , ct_var : ty :: Const < 'tcx > ,) -> ty :: Const < 'tcx > { debug_assert ! (! self . infcx . is_some_and (| infcx | ct_var != infcx . shallow_resolve_const (ct_var))) ; let var = self . canonical_var (var_kind , ct_var . into ()) ; let bc = ty :: BoundConst { var } ; ty :: Const :: new_bound (self . tcx , self . binder_index , bc) } }}}